diff --git a/server/include/assurance/observer_attribution.hpp b/server/include/assurance/observer_attribution.hpp
index 02027ae..caf0e89 100644
--- a/server/include/assurance/observer_attribution.hpp
+++ b/server/include/assurance/observer_attribution.hpp
@@ -111,6 +111,30 @@ struct ObserverAttributionResult {
     double observed_cpu_busy{0.0};
     bool cpu_available{false};

+    /**
+     * @brief 软中断构成的细分（仅 SELF_INFLICTED 分支有意义）
+     *
+     * CPU 忙只回答"采集端过载了"，回答不了"过载是网络收包造成的，
+     * 还是与网络无关的本机负载造成的"。这两者的处置方向完全相反：
+     *   NET_RX 主导 → 采集端在拼命处理**被观测链路**的流量，
+     *                 过载与观测对象强相关（流量是真的大）
+     *   其它主导   → 与网络无关的本机负载，才是真正意义的"自伤"
+     *
+     * 这一层细分**不改变** ObserverAttribution 枚举值（仍然是
+     * SELF_INFLICTED），只在 explanation 与 evidence 上补充说明。
+     * 理由：加枚举值要同步序列化契约、云端 schema、全部真值表测试，
+     * 而结论本身并没有多出一个新分类——只是把同一结论讲得更清楚。
+     */
+    double softirq_net_rx_share{0.0};
+    bool softirq_available{false};
+
+    /// 收包软中断占主导的判定阈值（默认 0.5）
+    ///
+    /// 注意：这是**事件计数**的构成比，不是时间占比。空载实测约 0.3%，
+    /// 线速小包洪水可达 99%，中间几乎没有分布。0.5 落在这段空白里，
+    /// 对"是不是收包把它压满的"这个问题足够可靠。
+    double softirq_share_threshold{0.5};
+
     /// 人类可读解释（进 warnings / 证据 detail）
     std::string explanation;

@@ -121,18 +145,30 @@ struct ObserverAttributionResult {
 /**
  * @brief 归因判定（无状态纯函数）
  *
- * @param sle          第 1 层评估结果（只读，不改）
- * @param sle_name     SLE 名称，进结果便于定位
- * @param cpu_busy     观测到的 CPU 忙率 0~1
- * @param cpu_available CPU 数据是否可用（false 时 cpu_busy 被忽略）
- * @param cfg          阈值配置
+ * @param sle                     第 1 层评估结果（只读，不改）
+ * @param sle_name                SLE 名称，进结果便于定位
+ * @param cpu_busy                观测到的 CPU 忙率 0~1
+ * @param cpu_available           CPU 数据是否可用（false 时 cpu_busy 被忽略）
+ * @param cpu_threshold           CPU 忙率达到多少算"过载"
+ * @param softirq_net_rx_share    收包软中断在全部软中断中的构成比 0~1
+ * @param softirq_available       软中断数据是否可用（false 时上一参数被忽略）
+ * @param softirq_share_threshold 构成比达到多少算"收包占主导"
  *
  * 判定规则：
  *   1. 若 sle.reason 不是已知的 observer 降级原因 → NONE，evaluated=false
  *   2. 若 CPU 数据不可用 → UNATTRIBUTED（不猜）
  *   3. CPU 忙率 >= 阈值 → SELF_INFLICTED
+ *      3a. 软中断数据可用时，在 explanation 与 evidence 上细分为
+ *          「收包路径主导」还是「非网络负载主导」
  *   4. 否则 → NOT_HOST_CPU_BOUND
  *
+ * 第 3a 步只加证据与解释，**不改枚举值**：分类结论仍是 SELF_INFLICTED，
+ * 只是把它讲清楚。加新枚举值会改序列化契约与云端 schema，而结论本身
+ * 并没有多出一个新分类。
+ *
+ * 软中断参数带默认值，是为了让既有调用点与真值表测试完全不受影响：
+ * 不传这些参数的调用，行为与引入本细分之前逐字一致。
+ *
  * 为什么用 reason 字符串前缀而不是给 SleResult 加枚举字段：
  * 加字段会改动所有 SleResult 生产者的初始化路径与全部下游序列化，
  * 收益却只是省一次字符串比较。reason 已经是稳定契约（有单元测试覆盖），
@@ -143,6 +179,9 @@ ObserverAttributionResult attributeObserverDegradation(
     const std::string& sle_name,
     double cpu_busy,
     bool cpu_available,
-    double cpu_threshold = 0.85);
+    double cpu_threshold = 0.85,
+    double softirq_net_rx_share = 0.0,
+    bool softirq_available = false,
+    double softirq_share_threshold = 0.5);

 }  // namespace weaknet
diff --git a/server/src/assurance/observer_attribution.cpp b/server/src/assurance/observer_attribution.cpp
index 094db1a..83e4499 100644
--- a/server/src/assurance/observer_attribution.cpp
+++ b/server/src/assurance/observer_attribution.cpp
@@ -39,11 +39,15 @@ ObserverAttributionResult attributeObserverDegradation(
     const std::string& sle_name,
     double cpu_busy,
     bool cpu_available,
-    double cpu_threshold) {
+    double cpu_threshold,
+    double softirq_net_rx_share,
+    bool softirq_available,
+    double softirq_share_threshold) {
     ObserverAttributionResult res;
     res.trigger_sle = sle_name;
     res.observer_reason = sle.reason;
     res.cpu_threshold = cpu_threshold;
+    res.softirq_share_threshold = softirq_share_threshold;

     // 1. 这个 SLE 根本没在报 observer 问题 → 不归因
     //
@@ -56,6 +60,8 @@ ObserverAttributionResult attributeObserverDegradation(
     res.evaluated = true;
     res.cpu_available = cpu_available;
     res.observed_cpu_busy = cpu_busy;
+    res.softirq_available = softirq_available;
+    res.softirq_net_rx_share = softirq_net_rx_share;

     // 2. 没有 CPU 数据 → 老实说不知道
     //
@@ -85,6 +91,36 @@ ObserverAttributionResult attributeObserverDegradation(
                                 "Observer degraded with high host CPU; suspect self-inflicted evidence loss"});
         res.evidence.push_back({"host_cpu_busy_ratio", cpu_busy,
                                 "Host CPU busy ratio at the time of observer degradation"});
+
+        // 3a. 细分：CPU 是被网络收包吃掉的，还是被别的负载吃掉的
+        //
+        // 这一步**不改 attribution**（仍是 SELF_INFLICTED），只补充一句
+        // 说明与一条证据。处置方向完全不同：
+        //   收包主导 → 采集端在处理被观测链路的流量，过载与观测对象相关
+        //   其它主导 → 与网络无关的本机负载，属真正意义上的"自伤"
+        //
+        // 软中断数据不可用时保持沉默，**不加任何猜测性的解释**——
+        // 与 UNATTRIBUTED 分支同一纪律：没数据就说没数据。
+        if (softirq_available) {
+            const bool rx_dominant = softirq_net_rx_share >= softirq_share_threshold;
+            if (rx_dominant) {
+                res.explanation +=
+                    "; softirq activity is dominated by the network receive path, so the collector "
+                    "was busy processing traffic from the observed link itself rather than an "
+                    "unrelated local workload";
+                res.evidence.push_back({"softirq_net_rx_share", softirq_net_rx_share,
+                                        "Network receive softirqs dominate all softirq activity; "
+                                        "CPU pressure correlates with observed traffic"});
+            } else {
+                res.explanation +=
+                    "; softirq activity is NOT dominated by the network receive path, so the "
+                    "collector was kept busy by an unrelated local workload instead of the "
+                    "observed link's traffic";
+                res.evidence.push_back({"softirq_net_rx_share", softirq_net_rx_share,
+                                        "Network receive softirqs do not dominate softirq activity; "
+                                        "CPU pressure comes from non-network local workloads"});
+            }
+        }
         return res;
     }

diff --git a/server/src/server.cpp b/server/src/server.cpp
index 6777505..518a380 100644
--- a/server/src/server.cpp
+++ b/server/src/server.cpp
@@ -595,10 +595,28 @@ void start_network_quality_thread(ServerContext* ctx, std::thread* worker) {
                             if (cpu_ok) cpu_busy = cpu_sample->value;
                         }

+                        // 软中断构成比：CPU_BUSY_RATIO 的限定词，回答"忙在哪"。
+                        //
+                        // 只有 cpu_ok 为真时才有意义——CPU 没饱和时下游根本
+                        // 不会咨询这个值（见 observer_attribution.cpp 第 3a 步）。
+                        // 这里仍然独立读取、独立判新鲜度，不复用 cpu 的可用性：
+                        // 两个模块是两个设备节点，一个缺失不影响另一个。
+                        double softirq_share = 0.0;
+                        bool softirq_ok = false;
+                        auto softirq_sample = ctx->metrics_registry->latest(
+                            "host:", weaknet::MetricId::SOFTIRQ_NET_RX_SHARE);
+                        if (softirq_sample) {
+                            softirq_ok = softirq_sample->isValid(
+                                weaknet::getMetricDescriptor(
+                                    weaknet::MetricId::SOFTIRQ_NET_RX_SHARE).freshness);
+                            if (softirq_ok) softirq_share = softirq_sample->value;
+                        }
+
                         // DNS 是当前唯一带 observer 质量门禁的 SLE。将来其它
                         // SLE 若也引入 observer 门禁，在这里并列追加即可。
                         auto attr = weaknet::attributeObserverDegradation(
-                            dns_sle, "dns_service", cpu_busy, cpu_ok);
+                            dns_sle, "dns_service", cpu_busy, cpu_ok,
+                            0.85, softirq_share, softirq_ok);
                         if (attr.evaluated) {
                             exp.observer_attribution = attr.attribution;
                             exp.observer_attribution_detail = attr.explanation;
@@ -623,7 +641,9 @@ void start_network_quality_thread(ServerContext* ctx, std::thread* worker) {
                                 << " reason=" << attr.observer_reason
                                 << " cpu_available=" << (attr.cpu_available ? "yes" : "no")
                                 << " cpu_busy=" << attr.observed_cpu_busy
-                                << " threshold=" << attr.cpu_threshold);
+                                << " threshold=" << attr.cpu_threshold
+                                << " softirq_available=" << (attr.softirq_available ? "yes" : "no")
+                                << " softirq_net_rx_share=" << attr.softirq_net_rx_share);
                         }
                     }

